/**
 * Marketing Post Repository
 *
 * Storage for Instagram posts generated by the internal content-creator tool.
 * Unlike the other repositories this one is backed by **S3, not Prisma**: a
 * post is a folder of PNGs plus a `manifest.json` written by the local
 * `npm run publish` script, so there is no table (and no RDS migration).
 *
 * Bucket: AWS_S3_POSTS_BUCKET (dedicated, private), falling back to AWS_S3_BUCKET.
 * Key layout:
 *   marketing-posts/{slug}/manifest.json   ← written last; a folder without it is incomplete
 *   marketing-posts/{slug}/{name}.png
 */

import {
  listSubPrefixes,
  listObjectKeys,
  getObject,
  deleteObjects,
  generateDownloadUrl,
} from '../s3';

export const PREFIX = 'marketing-posts/';

// Read per call so tests and runtime env changes are honoured.
const target = () => ({ bucket: process.env.AWS_S3_POSTS_BUCKET || undefined });

const keyFor = (slug, name) => `${PREFIX}${slug}/${name}`;

/** Slugs of every folder under the prefix (complete or not). */
export async function listSlugs() {
  const prefixes = await listSubPrefixes(PREFIX, target());
  return prefixes.map((p) => p.slice(PREFIX.length).replace(/\/$/, '')).filter(Boolean);
}

/**
 * Raw manifest JSON for a post, or null when the folder has no manifest.
 * Throws on malformed JSON so the service can skip the post.
 */
export async function findManifest(slug) {
  try {
    const obj = await getObject(keyFor(slug, 'manifest.json'), target());
    return JSON.parse(await obj.text());
  } catch (err) {
    if (err.code === 'NOT_FOUND') return null;
    throw err;
  }
}

/** Short-lived presigned GET URL for one file of a post. */
export function getFileUrl(slug, name, expiresIn = 3600) {
  return generateDownloadUrl(keyFor(slug, name), expiresIn, target());
}

/** Stream one file of a post. Throws `code: 'NOT_FOUND'` when missing. */
export function getFile(slug, name) {
  return getObject(keyFor(slug, name), target());
}

/** Delete every object of a post. Returns how many objects were removed. */
export async function removeAll(slug) {
  const keys = await listObjectKeys(`${PREFIX}${slug}/`, target());
  if (keys.length) await deleteObjects(keys, target());
  return keys.length;
}
